llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Levodopa, a zwitterionic amino acid with phenol and carboxylic acid groups, has absolute oral bioavailability of 71% in elderly volunteers despite very low passive permeability, demonstrating that active amino-acid transport can yield F≥20% for highly polar amino-acid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Baclofen, a zwitterionic amino-acid analogue with amine and carboxylic acid groups, has absolute oral bioavailability of 85.8% in healthy volunteers, supporting high F for polar amino-acid-like drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Desvenlafaxine, a phenolic amine with substantial polarity, has absolute oral bioavailability of approximately 80%, showing that phenolic/ionizable structures can still achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Garenoxacin, an oral antibacterial with a carboxylic acid and ionizable groups, has absolute oral bioavailability of 92%, supporting high F for an orally administered antibiotic with acidic functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Maraviroc has oral bioavailability of 33% in healthy subjects, above the 20% threshold, indicating that even compounds with transporter-limited absorption can meet the high-F criterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ezetimibe has oral bioavailability of 35–60%, above the 20% threshold, supporting high F despite extensive conjugation and metabolic liability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High oral bioavailability is supported by multiple high-transfer analogues with amino-acid, phenolic, and zwitterionic features showing absolute F values of 33–99%, all above the 20% threshold. The low passive-permeability prior is outweighed by evidence that such polar molecules can be absorbed via active/transporter-mediated pathways.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for a cephalosporin with a tetrazole-thiomethyl substituent is included.",
    "Beta-lactam gastrointestinal stability and intestinal PEPT1 transport are not directly evidenced for the query.",
    "Computational estimates of logD and TPSA may overestimate the permeability barrier if active uptake dominates absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

